import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        arr = []
        for _ in range(N):
            arr.append(int(next(iterator)))
    except StopIteration:
        return

    depth = [0] * N
    root = -1

    for i in range(N):
        if arr[i] == -1:
            root = i
            depth[i] = 0
        else:
            current = i
            while arr[current] != -1 and depth[arr[current]] == 0 and arr[current] != current:
                current = arr[current]

            if arr[current] == -1:
                d = 0
            elif depth[current] > 0:
                d = depth[current]
            else:
                d = 0

            temp = i
            path = []
            while temp != current and arr[temp] != -1:
                path.append(temp)
                temp = arr[temp]

            if arr[temp] == -1:
                base_depth = 0
            else:
                base_depth = depth[temp]

            for idx, node in enumerate(path):
                depth[node] = base_depth + len(path) - idx

    if root != -1:
        max_h = 0
        for i in range(N):
            if depth[i] > max_h:
                max_h = depth[i]
        print(max_h)
    else:
        print(0)

if __name__ == "__main__":
    main()
